#!/bin/sh
# Creates deploy/vps/.env with freshly generated IAPStack secrets.
# It refuses to overwrite an existing file: the protection keys and database password
# must stay stable for the lifetime of the PostgreSQL volume.
set -eu

cd "$(dirname "$0")"

if [ -e .env ]; then
  echo ".env already exists; refusing to replace existing secrets." >&2
  exit 1
fi

command -v openssl >/dev/null 2>&1 || { echo "openssl is required" >&2; exit 1; }

umask 077
cat > .env <<EOF
# Generated by init-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ).
# Copy this file to your password manager. Losing the protection keys makes stored
# store credentials and webhook secrets unreadable.

IAPSTACK_POSTGRES_PASSWORD=$(openssl rand -hex 32)
IAPSTACK_PROTECTION_ACTIVE_KEY_ID=primary
IAPSTACK_PROTECTION_KEYS='{"primary":"$(openssl rand -base64 32)"}'
IAPSTACK_PROTECTION_FINGERPRINT_KEY=$(openssl rand -base64 32)
IAPSTACK_METRICS_BEARER_TOKEN=$(openssl rand -base64 48 | tr -d '\n')

# Used once to create the first durable administrator key, then emptied.
IAPSTACK_BOOTSTRAP_ADMIN_KEY=$(openssl rand -base64 48 | tr -d '\n')

# Paste the connector token from Cloudflare Zero Trust → Networks → Tunnels, and set
# COMPOSE_PROFILES=tunnel so `docker compose up` also starts the connector.
CLOUDFLARE_TUNNEL_TOKEN=
COMPOSE_PROFILES=

IAPSTACK_ENVIRONMENT=production

# Optional tuning for 1 GB hosts (defaults suit 1-24 GB machines).
# IAPSTACK_POSTGRES_SHARED_BUFFERS=64MB
# IAPSTACK_WORKER_CONCURRENCY=1

# Optional Grafana Cloud OTLP export.
# IAPSTACK_GRAFANA_OTLP_ENDPOINT=
# IAPSTACK_GRAFANA_OTLP_USERNAME=
# IAPSTACK_GRAFANA_OTLP_TOKEN=

# Optional off-server backups: an rclone remote (ideally an rclone crypt remote) and path.
# IAPSTACK_BACKUP_RCLONE_TARGET=iapstack-crypt:
# IAPSTACK_BACKUP_KEEP_DAYS=14
EOF

echo "Wrote $(pwd)/.env (mode 600). Set CLOUDFLARE_TUNNEL_TOKEN and COMPOSE_PROFILES=tunnel to enable the tunnel."
